/* operator-actions.js - GENERATED by tools/build_operator_actions.py from platform-actions.html's script. Do not edit:
   edit the queues there, then regenerate (the operator-console gate fails while this file is not the current cut).

   The operator console's action queues (OPC, 2026-10-22): the credit position, the GCash top-ups and the receipts the
   automatic match left, listing and seller review, feedback triage, and who decided what. Nothing runs when this file
   loads. founder-console.html calls window.whOperatorActions.start({ realAdmin }) once its own admin gate has passed. */
(function () {
  const api = { started: false, refresh: null };
  api.start = async function start(opts) {
    if (api.started) return;
    api.started = true;
    opts = opts || {};
    const db = window.getDb();   // the console's own client (getDb returns the one already made)
    // BRH-H (2026-10-15): this console reads the hive only to stamp an operator's audit entry (hive_id is NOT NULL), at
    // the moment of an action - so a wiped one is seated from the account here, at parse time, instead of by the
    // after-load recovery's reload.
    if (typeof whStartupHive === 'function') {
      window.WH_SEATS_HIVE_ITSELF = true;
      whStartupHive(db).catch(() => {});
    }
    const e = (typeof escHtml === 'function') ? escHtml : (s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])));

    // Minimal toast (founder-console keeps its own; this page is standalone).
    function showToast(msg, kind) {
      const box = document.getElementById('opc-toast') || document.getElementById('toast');
      const el = document.createElement('div');
      el.className = 'toast-msg' + (kind ? ' ' + kind : '');
      el.textContent = msg;
      box.appendChild(el);
      setTimeout(() => el.remove(), 3200);
    }

    // SL L2 (2026-10-21): this console's decisions are recorded by the DATABASE (audit_platform_decision ->
    // platform_audit_log, read under "Recent decisions"). Its old writeAuditLog put each one into the operator's own
    // home hive trail - the only hive hive_audit_log let it write - where an unrelated hive's supervisors read it.

    /* SESSION-LIMITED, NOT ALL CLEAR. When the localhost bypass opened the console for someone who is
       not a platform admin, RLS returns 0 rows with no error — so every queue below is empty for a
       reason that has nothing to do with the work. The amber banner says so, but an empty state that
       still reads "all clear" contradicts it in the same viewport, and "all clear" is the affirmative
       claim: it asserts there is nothing waiting, which is exactly what we cannot know here. Found on
       a live walk with 4 drafts pending and the queue reporting all clear. */
    /* WHEN THE DATABASE REFUSES ON PURPOSE, SAY WHAT IT SAID. Our guards raise deliberate,
       person-shaped messages ("The lowest price WorkHive lists is PHP500. This one is PHP120 — bundle
       it with something, or raise the price"), and this page was throwing every one of them away
       behind "Action failed. Try again." — which is also FALSE, because retrying a rule violation
       fails identically forever. Found on a live walk of the new PHP500 floor: the guard was perfect
       and the screen was useless.
       23514 = check_violation, P0001 = a bare RAISE. Both mean a rule we wrote, deliberately, with a
       message meant to be read. Anything else (a network fault, a constraint we did not author) keeps
       the generic text, because a raw Postgres string is not an instruction. */
    /* 42501 CARRIES DELIBERATE, HUMAN-WRITTEN REFUSALS AND THEY WERE BEING THROWN AWAY. Measured
       2026-08-05: an admin who is also a seller pressed Approve on their own listing. The server
       refused with 42501 and the sentence the guard was written to say --

         "Not allowed: a listing goes live only after WorkHive review, not by self-publishing"

       -- and the console showed "Action failed. Try again." Retrying is the one thing that cannot
       work: the refusal is structural, and the actual next step (another admin reviews it) was in
       the message that got dropped. Only 23514 and P0001 were passed through.

       A raw 42501 can also be PostgREST's own "permission denied for table X", which tells an admin
       nothing, so the grant-shaped wording is still filtered out and falls back to the session
       branch below. */
    /* ONE VOCABULARY PER CONCEPT, and this queue had its own. A price of 0 means NEGOTIABLE across
       the whole platform -- the grid, the seller dashboard and the public profile all render it that
       way -- but the moderation row rendered a bare "₱0". A moderator deciding whether to publish a
       listing was reading a different fact from the one the seller entered and the buyer will see,
       and "₱0" reads like a mistake worth rejecting. Measured 2026-08-05 by injecting a zero-price
       and a null-price row into the queue.
       The moderator still needs the stored value, so say both where they differ, rather than picking
       one side and hiding the other. */
    function _modPrice(p) {
      if (p === null || p === undefined || p === '') return 'price not set';
      const n = Number(p);
      if (!isFinite(n)) return 'price unreadable';
      if (n === 0) return 'Negotiable (listed at ₱0)';
      return '₱' + n.toLocaleString();
    }

    function refusalMessage(err) {
      const code = String(err && (err.code || err.errcode) || '');
      const msg = String(err && err.message || '').trim();
      // 54000 (SL RL2, 2026-10-22): a limit refuses in its own sentence too - the daily caps say which limit and when
      if ((code === '23514' || code === 'P0001' || code === '54000') && msg && msg.length < 300) return msg;
      if (code === '42501' && msg && msg.length < 300
          && !/permission denied for (table|relation|schema|function|view|sequence)/i.test(msg)
          && !/jwt|token expired/i.test(msg)) return msg;
      return null;
    }

    let _sessionLimited = false;
    function emptyText(allClear) {
      return _sessionLimited
        ? 'Not visible with this session. Sign in as a platform admin to see what is waiting.'
        : allClear;
    }

    /* A RAW ERROR STRING IS NOT AN EXPLANATION, and for a 429 it is missing the only actionable half.
       These queues printed `m._error` verbatim, so a rate limit read "Couldn't load the queue: rate
       limit exceeded" -- it NAMES the limit and never says when it clears, which leaves an admin
       retrying, the one action that extends it. An expired session read the same way, with no hint
       that signing in is the fix. Same taxonomy the marketplace, seller, profile and community
       surfaces got this session. The raw text is kept in a title for whoever is debugging. */
    function _queueErr(m) {
      const st = m && m._status;
      const code = String((m && m._code) || '');
      const raw = String((m && m._error) || '');
      if (st === 429 || code === '429' || /rate limit/i.test(raw)) {
        const n = Number((m && m._retryAfter) || (raw.match(/(\d+)\s*s/) || [])[1]);
        const wait = (isFinite(n) && n > 0)
          ? (n < 60 ? Math.round(n) + ' seconds'
                    : Math.round(n / 60) + ' minute' + (Math.round(n / 60) === 1 ? '' : 's'))
          : 'a moment';
        return 'Too many requests. Your connection is fine: wait about ' + wait + ', then refresh.';
      }
      /* 401 = dead session; 403 = live session, refused row. On a moderation queue the difference is
         especially sharp: a 403 usually means this account is not a moderator, and "sign in again"
         invites them to keep trying an account that will never be allowed. Measured 2026-08-05 by
         injecting each status at the route layer across six surfaces. */
      /* A BARE 42501 IS A PERMISSION PROBLEM, NOT A SESSION ONE. Postgres raises 42501 for
         insufficient_privilege; a dead session surfaces as PGRST301 or a JWT message. Defaulting an
         unknown-status 42501 to "your session expired" put the session sentence in front of an admin
         whose session was fine — and it kept doing so even after the status started being carried,
         because the queue that renders this one still reports no status at all. */
      if (st === 401 || /jwt|token|expired/i.test(raw)) {
        // ...and say what happened to their work. A moderator mid-review needs to know whether the
        // decision they were about to make went anywhere; "your session expired" alone leaves them
        // guessing whether they approved something on the way out.
        return 'Your session expired. Sign in again to load this queue. Nothing was approved or '
             + 'rejected while it was expired.';
      }
      if (st === 403 || code === '42501') {
        return 'This account is not allowed to load this queue. Your session is fine, so signing in '
             + 'again will not change it. This queue needs moderator access.';
      }
      // ★"COULDN'T LOAD THIS QUEUE: NAME RESOLUTION FAILED" (2026-10-06, platform-actions x assistive-tech, PostgREST
      // stopped). The fallthrough appended the raw message, so an admin read the gateway's DNS words for an upstream
      // that was down. A 5xx or an unreachable upstream has one honest sentence, and this page's own retry control is
      // "Refresh queues", so the sentence names it.
      if ((st >= 500 && st <= 504) || /name resolution|service unavailable|bad gateway|timed? ?out|failed to fetch|network/i.test(raw)) {
        return (navigator.onLine === false)
          ? "You are offline, so this queue could not be loaded. Press Refresh queues when your connection is back."
          : "Couldn't load this queue - WorkHive did not answer. Press Refresh queues in a moment.";
      }
      return "Couldn't load this queue: " + raw;
    }

    async function fetchMktModeration() {
      try {
        // `marketplace_disputes` dropped 2026-08-03 — retired ghost table (0 rows, no client writer).
        const [drafts, sellers] = await Promise.all([
          db.from('v_marketplace_listings_truth')
            .select('id,title,section,category,price,seller_name,created_at')
            .eq('status', 'draft').order('created_at', { ascending: true }).order('id').limit(50 + 1),   // more-said: by renderMktModeration (SL LB1: a 51st draft is the probe) - no count or sum is derived from this read (classified by the reference-pages-uncapped sweep, 2026-09-05)
          db.from('v_marketplace_sellers_truth')
            .select('id,worker_name,tier,kyb_verified,cert_verified,certifications,active_listings_count,created_at')
            .or('kyb_verified.eq.false,cert_verified.eq.false').order('created_at', { ascending: false }).order('id').limit(50 + 1),   // more-said: by renderMktModeration (SL LB1: a 51st seller is the probe) - no count or sum is derived from this read (classified by the reference-pages-uncapped sweep, 2026-09-05)
        ]);
        /* CARRY THE CODE AND STATUS, NOT JUST THE SENTENCE. supabase-js reports a PostgREST failure
           through `error` rather than by throwing, so only the catch below was populating _code and
           _status — and _queueErr, which decides between "your session expired", "you are not allowed"
           and "check your connection", was left with neither. Every 401 and 403 therefore fell through
           to the generic "Couldn't load this queue: permission denied", naming no cause and no remedy.
           Measured 2026-08-05 by injecting a 401 at the route layer. */
        const _e = drafts.error || sellers.error;
        return {
          drafts: (drafts.data || []).slice(0, 50), sellers: (sellers.data || []).slice(0, 50),
          draftsMore: (drafts.data || []).length > 50, sellersMore: (sellers.data || []).length > 50,   // SL LB1
          _error: _e ? _e.message : null,
          _code: _e ? (_e.code || null) : null,
          _status: _e ? (_e.status || _e._httpStatus || null) : null,
        };
      } catch (err) { return { _error: err && err.message || 'fetch failed', _code: err && err.code || null, _status: err && (err._httpStatus || err.status) || null, _retryAfter: err && err.retryAfter || null }; }
    }

    /* GCash top-up verification — the founder-income intake. A provider sent GCash P2P to the platform
       number and filed the reference; the founder checks the GCash app, then Verify (a DB trigger mints
       the credits) or Reject. Every credit in the economy originates here, so this queue being reachable
       is not cosmetic: while it lived only on the retired founder-console, no credit could be minted. */
    // (The usage card's reads are not here: its one unique figure - what people used each page for - is drawn by the
    // console's Growth Pulse panel, beside the daily and monthly actives it already shows.)

    async function fetchSvcTopups() {
      try {
        // Truth view, not the raw table: it folds in provider_display_name so the queue does not N+1
        // the provider directory to name who is waiting.
        /* Bounded: this queue decides whether real money becomes credits, and an unbounded read left
           the founder staring at a queue that never resolves and never says why. whQueryTimeout hands
           back supabase's own {data,error} shape, so the _error/_code plumbing below is unchanged. */
        const _q = db.from('v_service_credit_topups_truth')
          .select('id, account_type, account_id, amount, gcash_ref, created_at, provider_display_name')
          .eq('status', 'pending_verification')
          .order('created_at', { ascending: true }).order('id').limit(50 + 1);   // more-said: by renderSvcTopups - the queue count says '50+' when a 51st is waiting (SL LB1)
        const { data, error } = await (typeof whQueryTimeout === 'function'
          ? whQueryTimeout(_q, 15000, 'the top-up queue') : _q);
        return { rows: (data || []).slice(0, 50), more: (data || []).length > 50, _error: error ? error.message : null,
                 _code: error ? (error.code || null) : null,
                 _status: error ? (error.status || error._httpStatus || null) : null };
      } catch (err) { return { rows: [], _error: err && err.message || 'fetch failed', _code: err && err.code || null, _status: err && (err._httpStatus || err.status) || null, _retryAfter: err && err.retryAfter || null }; }
    }

      /* A TOP-UP AMOUNT NOBODY COULD READ WAS RENDERING AS PHP0. `Number(null)` is 0, so an unreadable
       amount printed "PHP0 · ref 1005556667770" on the queue where an admin matches a filed GCash
       reference against a real payment BEFORE releasing credits. That is the worst place on the
       platform for a fabricated zero: it invites either dismissing a real payment as nothing, or
       releasing credits against a figure the screen never actually had. Say the amount is unreadable
       and let the admin go look at the reference. */
    const _amtOrGap = (v) => (v === null || v === undefined || v === '' || !isFinite(Number(v)))
      ? 'amount unreadable'
      : '₱' + Number(v).toLocaleString();

  function renderSvcTopups(m) {
      const box = document.getElementById('svc-topups-content');
      if (!box) return;
      m = m || {};
      if (m._error) {
        box.innerHTML = `<div class="mod-empty">${e(_queueErr(m))}</div>`;
        /* A FAILED READ WAS SETTING THE BADGE TO 0. "Top-ups 0" beside a card that just said it
           could not load tells an admin there is nothing waiting, on the queue where waiting means
           somebody has paid and is owed credits. Same shape as the cover badge fixed earlier, in the
           sibling queue: the failure path was writing the number instead of admitting the gap. */
        setCount('svc-topups-count', '—', '');
        return;
      }
      const rows = m.rows || [];
      if (!rows.length) {
        box.innerHTML = `<div class="mod-empty">${e(emptyText('No top-ups waiting. Filed references appear here for your GCash-app check.'))}</div>`;
      } else {
        box.innerHTML = rows.map(r => `
          <div class="mod-row">
            <div class="mod-main"><strong>${_amtOrGap(r.amount)} · ref ${e(r.gcash_ref)}</strong>
              <span class="mod-sub">${e(r.provider_display_name || r.account_type)} · filed ${e(new Date(r.created_at).toLocaleString('en-PH', { timeZone: 'Asia/Manila' }))}</span></div>
            <div class="mod-actions">
              <button class="mod-btn ok" data-topup-act="verify" data-id="${e(r.id)}" data-i="verifymintcredits">Verify: mint credits</button>
              <button class="mod-btn no" data-topup-act="reject" data-id="${e(r.id)}" data-i="reject">Reject</button>
            </div>
          </div>`).join('');
      }
      setCount('svc-topups-count', m.more ? '50+' : rows.length, 'warn');   // cap is not a total (2026-09-05); SL LB1: a 51st row decides it
    }

    // ── Recent decisions (SL L2, 2026-10-21) ──────────────────────────────────────────────────────────────────────
    // platform_audit_log is written by the database on every decision path (audit_platform_decision), the actor bound
    // to the account that acted. Platform admins read it (RLS); for anyone else the read returns zero rows with no
    // error, which emptyText() already words as "not visible with this session" rather than "nothing decided".
    async function fetchDecisions() {
      try {
        // canonical-allow: platform_audit_log is the platform's decision trail, read whole by the page that shows it - not a KPI
        const { data, error } = await db.from('platform_audit_log')
          .select('id, actor, action, target_type, target_id, target_name, meta, created_at')
          .order('created_at', { ascending: false })
          .order('id')   // MR4: created_at alone is not a total order
          .limit(20 + 1);   // more-said: by renderDecisions - 'latest 20' when a 21st exists (SL LB1)
        if (error) throw error;
        return { rows: (data || []).slice(0, 20), more: (data || []).length > 20, _error: null };
      } catch (err) {
        return { rows: [], _error: (err && err.message) || 'fetch failed', _code: (err && err.code) || null };
      }
    }
    function renderDecisions(m) {
      const box = document.getElementById('decisions-list');
      if (!box) return;
      m = m || {};
      if (m._error) {
        box.innerHTML = `<div class="mod-empty">${e(_queueErr(m))}</div>`;
        setCount('decisions-count', '—', '');
        return;
      }
      const rows = m.rows || [];
      if (!rows.length) {
        box.innerHTML = `<div class="mod-empty">${e(emptyText('No decisions yet. Each top-up, listing, seller and feedback decision made here appears with who made it.'))}</div>`;
      } else {
        box.innerHTML = rows.map(r => {
          const v = (typeof whAuditView === 'function') ? whAuditView(r)
            : { label: String(r.action || ''), target: String(r.target_name || '') };
          const reason = r.meta && r.meta.reason ? ' · reason: ' + r.meta.reason : '';
          return `
          <div class="mod-row">
            <div class="mod-main"><strong>${e(v.label)}${v.target ? ': ' + e(v.target) : ''}</strong>
              <span class="mod-sub">${e(r.actor || 'unknown')} · ${e(new Date(r.created_at).toLocaleString('en-PH', { timeZone: 'Asia/Manila' }))}${e(reason)}</span></div>
          </div>`;
        }).join('');
      }
      setCount('decisions-count', m.more ? 'latest 20' : rows.length, '');   // a cap is not a total; SL LB1: a 21st row decides it
    }

    let _svcTopupWired = false;
    function wireSvcTopups() {
      if (_svcTopupWired) return; _svcTopupWired = true;
      document.getElementById('sec-svc-topups').addEventListener('click', async (ev) => {
        const btn = ev.target.closest('button[data-topup-act]');
        if (!btn) return;
        const verify = btn.dataset.topupAct === 'verify';
        /* A DEAD BUTTON THAT SAYS NOTHING. This one greyed out with no label change and no aria-busy
           while the write was in flight -- on the founder's money queue, where the next thing that
           happens is credits minted to a provider's wallet. Its sibling handler (listing moderation)
           already announces itself; this one did not, so a slow round-trip read as "my press did
           nothing". Same treatment here: say what is happening, and restore on EVERY path, not only
           the error one -- the success path relied on refreshQueues() replacing the node, which is
           true until a refresh fails and leaves a permanently dead control behind. */
        // T67/T50 (2026-08-26): the same gap fixed on founder-console, present here too - this
        // console mints credits on a single click. The optimistic lock below stops a DOUBLE press;
        // it cannot stop a WRONG-ROW press, and these are per-row buttons in a queue worked at
        // speed. Confirm before the busy state, so a cancel leaves the control exactly as it was.
        if (typeof window.whConfirm === 'function') {
          const _okTopup = await window.whConfirm(
            verify
              ? 'Verify this top-up? Credits are minted into the provider’s wallet immediately '
                + 'and spending them cannot be reversed from here.'
              : 'Reject this top-up? The provider paid for it, so no credits are minted and they '
                + 'will need to raise it with you directly.',
            { okLabel: verify ? 'Verify and mint' : 'Reject', cancelLabel: 'Cancel' });
          if (!_okTopup) return;
        }
        const _label = btn.textContent;
        const _restore = () => { btn.disabled = false; btn.removeAttribute('aria-busy');
                                 btn.textContent = _label; };
        btn.disabled = true;
        btn.setAttribute('aria-busy', 'true');
        btn.textContent = verify ? 'Verifying…' : 'Rejecting…';
        try {
          /* Optimistic lock on the ORIGINATING status: the founder works this queue by hand at speed,
             so a double-press is the expected human error, not an exotic one. Filtering on
             pending_verification means the second press changes 0 rows and says so, rather than
             re-deciding a row another admin already settled. */
          const { data, error } = await db.from('service_credit_topups')
            .update({ status: verify ? 'verified' : 'rejected' })
            .eq('id', btn.dataset.id).eq('status', 'pending_verification').select('id');
          if (error) throw error;
          if (!data || !data.length) {
            showToast('No change saved: that top-up was already decided.', 'error');
          } else {
            // SL L2: the decision is recorded by the database (audit_platform_decision -> platform_audit_log, and
            // verified_by / verified_at on the top-up itself) - this page no longer writes it into its own hive's trail
            showToast(verify
              ? 'Verified. Credits minted to the provider\'s wallet.'
              : 'Rejected. No credits were minted.', verify ? 'success' : 'info');
            if (typeof whUse === 'function') whUse(db, verify ? 'topup_verified' : 'topup_rejected');
          }
          await refreshQueues();
          _restore();
        } catch (err) {
          console.error('[platform-actions] top-up decision failed:', err);
          showToast(refusalMessage(err)
            || (whIsAuthFailure(err)
                ? 'Your admin session expired, so nothing was changed. Sign in again to continue.'
                : _t('We could not record that decision, and nothing changed. Try again.', 'Hindi naitala ang desisyong iyon, at walang na-mint. Subukan muli.')), 'error');
          _restore();
        }
      });
    }

    let _gcashCount = null;   // exact server count of receipts needing eyes (set by the fetch, read by the badge)
    function setCount(id, n, level) {
      const el = document.getElementById(id);
      if (!el) return;
      /* ★A QUEUE YOU MAY NOT READ HAS AN UNKNOWN SIZE, NOT A SIZE OF ZERO (2026-10-06, found walking
         LXP223 as a worker). Every counter here already dashes on `m._error` - but an RLS refusal is not an
         error: it returns ZERO ROWS and no error at all, so the counts computed 0 and printed it. Measured
         against the database: platform_feedback holds 10 rows with status 'new' while this page's New tab
         read 0, directly beside its own list saying "Not visible with this session. Sign in as a platform
         admin to see what is waiting." The list was honest and the counters contradicted it on the same
         screen - the same two-elements-disagreeing shape logbook and inventory each had.
         `_sessionLimited` is the page's OWN existing signal for this state (emptyText() keys on it), so the
         fix is to make the counters obey the verdict the page has already reached, in the one function they
         all pass through rather than at ten call sites. */
      if (typeof _sessionLimited !== 'undefined' && _sessionLimited) {
        /* ...and the dash carries WORDS, because it means "unknown" to the eyes only. Measured on
           inventory.html the same day: three pills reading "— parts" with no accessible name, which a
           screen reader announces as "parts" with no value at all. whStatUnknown names it; whStatValue
           below REMOVES that name when a real figure lands, so a stale label can never be read instead of
           the live number. The id is the only label available here (setCount is generic), so it is
           humanised - 'fb-count-new' reads as 'new'. */
        if (typeof whStatUnknown === 'function') {
          whStatUnknown(el, String(id || '').replace(/^.*?-count-?/, '').replace(/[-_]/g, ' ').trim().replace(/^badge$/, 'feedback waiting') || null);
        } else {
          el.textContent = '\u2014';
        }
        el.className = 'count';
        return;
      }
      if ((n === '—' || n === '-') && typeof whStatUnknown === 'function') {
        // A failed read passes the dash in as a VALUE (applyFeedbackView's error path does); routing it through
        // whStatValue printed a bare dash a screen reader cannot speak (2026-10-06, assistive-tech walk).
        whStatUnknown(el, String(id || '').replace(/^.*?-count-?/, '').replace(/[-_]/g, ' ').trim().replace(/^badge$/, 'feedback waiting') || null);
        el.className = 'count';
        return;
      }
      if (typeof whStatValue === 'function') whStatValue(el, n); else el.textContent = n;
      /* ONLY AN EMPTY QUEUE DROPS THE LEVEL (2026-10-23). `n > 0` held for a number and was false for every
         formatted figure: '50+' > 0 and '0.75x' > 0 are both false in JS, so a capped queue never turned amber
         and liability cover below 1.00x never turned red - the one signal the retired RAG dot existed to give. */
      el.className = 'count' + (level && !(typeof n === 'number' && n <= 0) ? ' ' + level : '');
    }

    // dashboard-allow: platform-actions is a governance ACTION-QUEUE console (approve/verify/resolve),
    // NOT a canonical KPI dashboard. It reads v_marketplace_listings_truth etc. only to build
    // moderation WORKLISTS; the counts shown are queue sizes ("N awaiting review"), not reported
    // canonical metrics. By explicit design (see the header sub-copy) EVERY metric lives in Grafana,
    // so the per-tile source-chip provenance pattern (provenance for a reported number) does not apply.
    function renderMktModeration(m) {
      m = m || {};
      // Listings awaiting review
      const lc = document.getElementById('mkt-listings-content');
      if (lc) {
        if (m._error) lc.innerHTML = `<div class="mod-empty">${e(_queueErr(m))}</div>`;
        else if (!(m.drafts || []).length) lc.innerHTML = `<div class="mod-empty">${e(emptyText(_t('No listings waiting: all clear.', 'Walang naghihintay na listing: all clear.')))}</div>`;
        /* AN ADMIN WHO IS ALSO A SELLER WAS OFFERED APPROVE ON THEIR OWN LISTING. The guard refuses
           it -- correctly, since self-publishing is exactly what review exists to prevent -- so that
           button could never do anything but fail. Don't offer an action that cannot succeed: say
           whose listing it is and what actually unblocks it. Reject stays, because withdrawing your
           own listing is not self-dealing.
           whWorker() is the same shared accessor the moderation record already uses for
           moderated_by, so the button and the audit trail can never disagree about who is acting. */
        else lc.innerHTML = m.drafts.map(l => { const _me = (typeof whWorker === 'function' && whWorker()) || null;
          const _mine = !!(_me && l.seller_name && String(l.seller_name).trim() === String(_me).trim()); return `
          <div class="mod-row">
            <div class="mod-main"><strong>${e(l.title || 'Untitled')}</strong>
              <span class="mod-sub">${e(l.section || '')}${l.category ? ' · ' + e(l.category) : ''} · ${_modPrice(l.price)} · ${e(l.seller_name || '\u2014')}</span></div>
            ${_mine ? '<span class="mod-sub" style="display:block;margin-top:0.2rem;">Your own listing: another admin has to review this one.</span>' : ''}
            <div class="mod-actions">
              ${_mine ? '' : `<button class="mod-btn ok" data-mkt-act="approve-listing" data-id="${e(l.id)}" data-i="approve">Approve</button>`}
              <button class="mod-btn no" data-mkt-act="reject-listing" data-id="${e(l.id)}" data-i="reject">Reject</button>
            </div>
          </div>`; }).join('');
      }
      /* A BADGE MUST NOT ASSERT A COUNT FROM A READ THAT FAILED (found 2026-08-08 by injecting a 500
         into the moderation reads as a verified admin). The pane above handles m._error and says so,
         but this line ran UNCONDITIONALLY: on a failed read `m.drafts` is undefined, `(m.drafts ||
         []).length` is 0, and the badge asserted "0 listings awaiting review" beside a pane that was
         simultaneously reporting the failure -- a screen disagreeing with ITSELF, which is worse than
         one merely stale, because the admin cannot tell which half to believe. On a moderation queue
         a 0 is a false ALL-CLEAR: it says nothing needs review when the truth is that nobody knows.
         This is the same defect this file already fixed for the top-up queue (:482) and the feedback
         queue (:1022), both of which set an em-dash on error; these two marketplace badges were the
         ones never given that branch. An em-dash asserts nothing, which is the only honest answer. */
      setCount('mkt-listings-count', m._error ? '—' : (m.draftsMore ? '50+' : (m.drafts || []).length), m._error ? '' : 'warn');   // the read is capped at 50: say so

      // Sellers awaiting verification
      const sc = document.getElementById('mkt-sellers-content');
      let sellerCount = 0;
      if (sc) {
        if (m._error) sc.innerHTML = `<div class="mod-empty">${e(_queueErr(m))}</div>`;
        else {
          const rows = (m.sellers || []).map(s => {
            const parts = [];
            // W45988 audit: these buttons announced as bare "Verify ID" - twelve of them at once,
            // one per seller, identical to a screen reader with nothing to say WHOSE identity each
            // one verifies. The name was already on the element in data-name and in the row's own
            // text; it just was not in the accessible name. On an action that marks a real person's
            // ID as checked, pressing the wrong row is the whole risk, so the label now carries the
            // person. English rather than hooked to a dictionary because this admin console ships no
            // translation pass at all - measured: zero data-i-aria, no whI18nApply, no dictionary
            // entry for verifyid - and declaring an i18n hook nothing implements is the
            // mechanism-that-is-not-a-mechanism this bank records.
            if (!s.kyb_verified) parts.push(`<button class="mod-btn ok" data-mkt-act="verify-kyb" data-name="${e(s.worker_name)}" data-seller-id="${e(s.id)}" aria-label="Verify ID for ${e(s.worker_name)}" data-i="verifyid">Verify ID</button>`);
            if (!s.cert_verified && s.certifications) parts.push(`<button class="mod-btn ok" data-mkt-act="verify-cert" data-name="${e(s.worker_name)}" data-seller-id="${e(s.id)}" aria-label="Verify certifications for ${e(s.worker_name)}" data-i="verifycerts">Verify certs</button>`);
            if (!parts.length) return '';
            sellerCount++;
            return `
            <div class="mod-row">
              <div class="mod-main"><strong>${e(s.worker_name)}</strong>
                <span class="mod-sub">${e(s.tier || 'bronze')} · ${s.active_listings_count || 0} listing(s)${s.certifications ? ' · has certs' : ''}</span></div>
              <div class="mod-actions">${parts.join('')}</div>
            </div>`;
          }).join('');
          sc.innerHTML = rows || `<div class="mod-empty">${e(emptyText('Every seller is verified.'))}</div>`;
        }
      }
      /* Same defect, and worse here because it is invisible in the source: sellerCount is only ever
         incremented INSIDE the success branch's map, so on a failed read it is still 0 and this line
         asserted "0 sellers awaiting verification" while the pane beside it reported the failure. A
         reader auditing this line alone sees a variable, not a fallback, which is exactly why the 500
         injection found it and four greps did not. Gated on the same m._error the pane uses, so the
         badge and the pane can no longer disagree about whether the read happened. */
      setCount('mkt-sellers-count', m._error ? '—' : (m.sellersMore ? '50+' : sellerCount), m._error ? '' : 'warn');   // the read is capped at 50: say so

      /* The "Open disputes" renderer was RETIRED 2026-08-03 with its table. Its honest-empty copy
         ("none can arrive") was the right fix for a queue that had to stay; deleting the queue is the
         better one. Its "Refund buyer" button promised money the platform never holds. */
    }

    /* The leftovers of automatic verification. Read separately so a failure here costs this card and
       never the top-up queue above it — the queue that mints credits must not go dark because a
       reporting view had a bad day. */
    async function fetchGcashLeftovers() {
      try {
        // Bounded, same as the top-up queue above: unreviewed GCash receipts are money waiting on a
        // human, and a stalled read that never resolves reads as "nothing to review".
        const _q = db.from('v_gcash_receipts_needing_eyes')
          .select('reference, amount, sender_name, received_at, match_state, match_note, created_at', { count: 'exact' }).limit(20);   // more-said: by renderGcashLeftovers - the badge paints the EXACT server count; the list shows the first 20 and says so (P355 a claim a query enforces, 2026-09-05)
        const { data, error, count } = await (typeof whQueryTimeout === 'function'
          ? whQueryTimeout(_q, 15000, 'the GCash receipts') : _q);
        _gcashCount = (typeof count === 'number') ? count : null;
        // Carry the CODE, not just the message: the renderer distinguishes a permission boundary
        // (42501, expected for anyone who is not a platform admin) from a genuine load failure, and
        // a message string alone would force it to pattern-match English.
        return { rows: data || [], _error: error ? error.message : null,
                 _code: error ? (error.code || null) : null,
                 _status: error ? (error.status || error._httpStatus || null) : null };
      } catch (err) { return { rows: [], _error: err && err.message || 'fetch failed', _code: err && err.code || null, _status: err && (err._httpStatus || err.status) || null, _retryAfter: err && err.retryAfter || null }; }
    }

    /* HIDDEN WHEN EMPTY, and that is deliberate: with the forwarder not yet configured this table is
       empty forever, and a permanently-empty card reads as a dead feed — the same reason the "Earned
       revenue" tile was deleted rather than left at zero. It appears the moment there is something
       to act on. */
    function renderGcashLeftovers(m) {
      const card = document.getElementById('sec-gcash-receipts');
      const box = document.getElementById('gcash-receipts-content');
      if (!card || !box) return;
      m = m || {};
      const rows = m.rows || [];
      /* A PERMISSION REFUSAL IS NOT A LOAD FAILURE. mig 43 made this view security_invoker and took
         the read from anon, so a signed-out visitor on the localhost bypass now gets 42501 instead
         of an empty list. Painting "Couldn't load" for that would be false twice over: nothing is
         broken, and retrying cannot help. It is the same boundary _sessionLimited already names for
         every other queue on this page, so say that and keep the card hidden — there is nothing to
         act on either way. */
      if (m._error && (typeof whIsAuthFailure === 'function' ? whIsAuthFailure({ code: m._code, message: m._error })
                                                             : /permission denied|42501/i.test(m._error))) {
        card.hidden = true;
        return;
      }
      if (m._error) {
        card.hidden = false; box.innerHTML = `<div class="mod-empty">${e(_queueErr(m))}</div>`;
        const _gc = document.getElementById('gcash-receipts-count');
        if (_gc && typeof whStatUnknown === 'function') whStatUnknown(_gc, 'receipts');
        return;
      }
      if (!rows.length) { card.hidden = true; return; }
      card.hidden = false;
      const WHY = {
        unmatched:       'No filing yet',
        ambiguous:       'Several filings share this reference',
        amount_mismatch: 'Amount disagrees',
        already_decided: 'Already decided',
      };
      box.innerHTML = rows.map(r => `
        <div class="mod-row">
          <div class="mod-main"><strong>${_amtOrGap(r.amount)} · ref ${e(r.reference)}</strong>
            <span class="mod-sub">${e(WHY[r.match_state] || r.match_state)}${r.sender_name ? ' · from ' + e(r.sender_name) : ''} · ${r.received_at
              /* ★THE TIME THE FOUNDER MATCHES ON (OPC walk, 2026-10-22): this printed created_at, unlabelled - when the forwarded
                 receipt reached WorkHive. The founder checks a receipt against the GCash app, which lists GCash's own time, the
                 receipt's received_at. Seeded receipts showed today beside a July payment. Both times are named now. */
              ? 'GCash time ' + e(new Date(r.received_at).toLocaleString('en-PH', { timeZone: 'Asia/Manila' }))
              : 'reached WorkHive ' + e(new Date(r.created_at).toLocaleString('en-PH', { timeZone: 'Asia/Manila' }))}</span>
            <span class="mod-sub">${e(r.match_note || '')}</span></div>
        </div>`).join('');
      setCount('gcash-receipts-count', (typeof _gcashCount === 'number' ? _gcashCount : rows.length), 'warn');   // exact count, not the 20-row page
      // SL LB1: the list is the first 20 of the badge's count - under the list, say so
      if (typeof whMoreNote === 'function') whMoreNote(box, { shown: rows.length, total: _gcashCount,
        more: typeof _gcashCount === 'number' && _gcashCount > rows.length, noun: 'receipts', order: 'first', src: 'v_gcash_receipts_needing_eyes' });
    }

    /* THE PLATFORM'S OWN MONEY POSITION. Both halves come from v_credit_posture, never from
       credit_treasury or service_credit_ledger raw: the cap is guarded by a CHECK constraint on that
       row, so the number a founder acts on must come from the view that publishes it, not from a sum
       here that could quietly disagree. That is the same canonical rule the drift ratchet enforces,
       and reading the base table is what tripped it earlier today. */
    async function fetchCreditPosition() {
      try {
        // SL LB2 (2026-10-20): the totals come from the database (get_credit_ledger_totals, one row per entry type). The
        // card used to sum a read capped at 2,000 ledger rows in the browser - past 2,000 entries the liability and
        // cover silently stopped counting the rest, and the read grew with every entry.
        const [posture, ledger] = await Promise.all([
          db.from('v_credit_posture').select('authorised_credits, issued_credits').maybeSingle(),
          db.rpc('get_credit_ledger_totals'),
        ]);
        if (posture.error) throw posture.error;
        if (ledger.error)  throw ledger.error;      // a failed read is not an empty ledger
        /* A REFUSAL CAN ARRIVE AS NULLS INSTEAD OF AN ERROR (2026-08-04, mig 47). v_credit_posture
           has no top-level FROM, so it ALWAYS returns exactly one row; its money columns are
           scalar sub-selects over credit_treasury. Once that table became admin-only, a non-admin
           stopped getting 42501 and started getting a row whose values are NULL — and Number(null)
           is 0, so the card would have rendered "supply 0 · issued 0 · liability PHP0.00": a
           confident, false claim that the platform holds no money at all. Same family as a failed
           read painting an empty state, except the read SUCCEEDED and the refusal hid in the data.
           Treat null money columns as the permission boundary they are. */
        const p = posture.data;
        if (!p || p.authorised_credits === null || p.issued_credits === null) {
          return { posture: null, totals: [], _error: 'permission denied', _code: '42501' };
        }
        return { posture: p, totals: ledger.data || [], _error: null };
      } catch (err) {
        return { posture: null, totals: [], _error: err && err.message || 'fetch failed', _code: err && err.code || null };
      }
    }

    function renderCreditPosition(m) {
      const box = document.getElementById('cp-content');
      if (!box) return;
      m = m || {};
      if (m._error) {
        // A permission boundary is not a fault: a non-admin simply may not see the platform's books.
        const boundary = m._code === '42501' || /permission denied/i.test(m._error);
        /* The boundary branch was already right; the OTHER branch still printed the raw string, so a
           rate limit on the solvency card read "Couldn't load the credit position: rate limit
           exceeded" -- naming the limit and never the wait, which is the half an admin can act on.
           _queueErr covers 429 and 401 and falls back to the original sentence otherwise. */
        box.innerHTML = `<div class="mod-empty">${e(boundary
          ? emptyText('Not visible with this session - sign in as a platform admin to see the credit position.')
          : _queueErr(m))}</div>`;
        /* NOT ZERO. The card correctly says "not visible with this session", and then this badge
           said "0" beside it -- and on a solvency console a cover of 0 does not read as "unknown",
           it reads as "the platform cannot cover its liabilities at all". The markup's own initial
           value is the gap character; the refusal path should return to it rather than invent the
           most alarming number on the page. Found by the AZ null-field induction 2026-08-04. */
        setCount('cp-cover', '\u2014', '');
        return;
      }
      /* YOU CANNOT TOTAL A COLUMN THAT CONTAINS AN UNKNOWN. `Number(r.amount || 0)` treated a NULL
         amount as zero, so a ledger row whose amount could not be read simply did not count -- and
         the tile still printed a confident peso figure. With the amounts nulled by the AZ induction
         the liability rendered "₱0.00": the platform owes nothing. That is the single most flattering
         reading available, invented from missing data, on the console that decides solvency, and it
         is the same class as the ₱300 top-up that printed as ₱0.00.
         A sum over rows containing an unreadable amount is UNKNOWN, and unknown propagates: every
         figure derived from it renders as a gap instead of a number. Real rows always carry an
         amount, so nothing changes in the healthy case -- this only fires when the data is missing,
         which is exactly when the wrong number does the most damage. */
      // one total per entry type from get_credit_ledger_totals (SL LB2): an entry type with any unreadable amount is
      // unknown, exactly as a row-by-row sum treated it; an entry type with no rows is zero
      const sum = t => {
        const row = (m.totals || []).find(r => r.entry_type === t);
        if (!row) return 0;
        const n = Number(row.total);
        if (Number(row.unreadable) > 0 || row.total === null || row.total === undefined || !isFinite(n)) return null;
        return n;
      };
      const add = (...xs) => xs.some(x => x === null) ? null : xs.reduce((a, b) => a + b, 0);
      /* CASH IN IS THE TOP-UPS; CREDITS OWED IS THE WHOLE LEDGER (2026-10-23). This read
         `topups = topup + starter_grant` and a liability of five hand-picked entry types. A starter grant is
         free credit issued against the supply cap - no peso enters - so it sat in the CASH half of the ratio,
         and adjustment / holding_fee / reward_* / voucher_reimburse never reached the owed half at all.
         Measured on the local ledger: 1500 topup + 3500 starter_grant + 200 adjustment - 360 commission. The
         tile read 1.08x; cash in over credits owed is 1500 / 4840 = 0.31x. An account's balance is the sum
         of every ledger row on it (person_credit_balance), so what the platform owes is every row, any type. */
      const topups   = sum('topup');
      const liability = (m.totals || []).length
        ? add(...(m.totals || []).map(r => sum(r.entry_type))) : 0;
      /* COVER COUNTED THE COMMISSION TWICE (found 2026-08-04, BC-ufai-F money_matches_ledger walk:
         the tile read 1.63 while cash-in / credits-owed is 1.32).
         The numerator was `topups + earned`. But commission is taken IN CREDITS, not in new cash —
         verified in the ledger: the three commission rows are NEGATIVE amounts on PROVIDER accounts
         (-200, -80, -80) with NO positive platform leg, and issued_credits does not move when one
         fires (1500 issued still equals the minting-only ledger sum exactly). No peso enters the
         business when commission is taken; 360 credits simply leave circulation.
         So that 360 is already inside the 1500 of top-up cash, and its benefit is ALREADY expressed
         in the DENOMINATOR — liability fell from 1500 to 1140 precisely because of it. Adding it to
         the numerator as well overstated solvency by 24% on the one tile whose entire job is to say
         "keep at or above 1.00". An overstated cover is exactly the wrong error on a ratio designed
         to warn about approaching insolvency.
         Cover is cash in / credits owed. Nothing else. */
      const cover = (liability !== null && topups !== null && liability > 0) ? topups / liability : null;
      const supply = m.posture ? Number(m.posture.authorised_credits) : null;
      const issued = m.posture ? Number(m.posture.issued_credits) : null;
      /* `Number(n || 0)` IS THE FABRICATED ZERO, and this is the last page it belongs on. The two
         tiles above already learned it: an unknown cover renders as a gap, because 0 on a solvency
         console does not read as "unknown", it reads as "the platform cannot cover its liabilities".
         These two formatters still had it, so a NULL liability printed "₱0.00" -- we owe nothing --
         and a null authorised/issued figure printed "0" credits, with `supply - issued` going through
         NaN to reach 0 as well. Every one of those is the most flattering reading available, invented
         by a formatter, on the page that decides whether the business is solvent.
         Absent renders as a gap. It is the same rule the top-up queue got when a filed ₱300 printed
         as ₱0.00, and the AZ null-field induction found it again here. */
      const gap = '—';
      const peso = n => (n === null || n === undefined || !isFinite(Number(n)))
        ? gap : '₱' + Number(n).toLocaleString(undefined, { minimumFractionDigits: 2 });
      const num  = n => (n === null || n === undefined || !isFinite(Number(n)))
        ? gap : Number(n).toLocaleString();

      // same reason as the refusal branch above: an unknown cover is a gap, never a 0, because 0 is
      // the reading that says the platform is insolvent
      /* WITH ITS UNIT. The row below this tile reads "1.32x"; the tile read a bare "1.32", and on a
         console where every other headline figure is pesos, a bare decimal beside "Credit position"
         invites being read as money. The \u00d7 is what makes it a ratio. */
      setCount('cp-cover', cover === null ? '\u2014' : cover.toFixed(2) + 'x',
               cover === null ? '' : (cover >= 1 ? '' : (cover >= 0.8 ? 'warn' : 'fail')));

      box.innerHTML =
        `<div class="mod-row"><div class="mod-main"><strong>${e(peso(liability))}</strong>
           <span class="mod-sub">Credit liability: services owed, not profit</span></div></div>`
      + `<div class="mod-row"><div class="mod-main"><strong>${e(cover === null ? '\u2014' : cover.toFixed(2) + 'x')}</strong>
           <span class="mod-sub">Liability cover: cash in vs credits owed; keep at or above 1.00</span></div></div>`
      + (supply === null ? '' :
          `<div class="mod-row"><div class="mod-main"><strong>${e(num(supply))}</strong>
             <span class="mod-sub">Total WorkHive Credits: the cap; lifetime liability cannot exceed it</span></div></div>`
        + `<div class="mod-row"><div class="mod-main"><strong>${e(num(issued))}</strong>
             <span class="mod-sub">Credits issued: minted into circulation so far</span></div></div>`
        + `<div class="mod-row"><div class="mod-main"><strong>${e(num(
              (supply === null || issued === null) ? null : supply - issued))}</strong>
             <span class="mod-sub">Credits available to issue: still unissued in the treasury</span></div></div>`
        + `<div class="mod-row"><div class="mod-main"><strong>1 credit = ₱1</strong>
             <span class="mod-sub">Fixed, and never moves</span></div></div>`)
      + (liability <= 0
          ? `<div class="mod-empty">No credits are outstanding yet. These figures start moving on the first verified top-up.</div>`
          : '');
    }

    async function refreshQueues() {
      /* The 60-second poll must NOT refetch feedback while a triage drawer is open. Swapping
         _fb.rows under an open editor replaces the updated_at snapshot the optimistic-concurrency
         guard compares against — so a save would silently overwrite the very edit the guard exists
         to catch, and the typed note would be judged against a row the admin never saw. The realtime
         channel still delivers new arrivals; only the reload is deferred. */
      /* SEVEN READS IN FLIGHT AND THE PAGE SAID NOTHING. Measured 2026-08-04: requestsInFlight 7,
         skeletonNodes 0, saysLoading false, busySignals 0 -- so every refresh, including the manual
         "Refresh queues" and the 60-second poll, left the queues showing their PREVIOUS contents with
         no sign that anything was happening. On a moderation console that is worse than a blank: the
         admin is looking at a list that may already be answered, believing it is current, and the
         only clue is a "Updated HH:MM:SS" stamp that has not moved yet.
         Marking the queue containers aria-busy costs nothing, does not disturb the rows already on
         screen (the admin can keep reading them), and is cleared by the renderers below on every
         path, success or failure, because they all overwrite innerHTML. */
      const _boxes = ['svc-topups-content', 'mkt-listings-content', 'gcash-receipts-content', 'cp-content', 'decisions-list']
        .map(id => document.getElementById(id)).filter(Boolean);
      const _sync = document.getElementById('last-sync');
      _boxes.forEach(b => b.setAttribute('aria-busy', 'true'));
      if (_sync) _sync.textContent = 'Refreshing…';
      const wantFeedback = !_fb.drawerId;
      try {
        // the usage card's figures are the console's Growth Pulse panel (OPC): no usage reads from here
        const [mod, tops, gcash, fb, cp, decided] = await Promise.all([
          fetchMktModeration(), fetchSvcTopups(), fetchGcashLeftovers(),
          wantFeedback ? fetchFeedback() : Promise.resolve(null),
          fetchCreditPosition(), fetchDecisions()]);
        renderMktModeration(mod);
        renderSvcTopups(tops);
        renderGcashLeftovers(gcash);
        if (fb) renderFeedback(fb);
        renderCreditPosition(cp);
        renderDecisions(decided);
        if (_sync) _sync.textContent = 'Updated ' + new Date().toLocaleTimeString('en-PH', { timeZone: 'Asia/Manila' });
      } catch (err) {
        // The busy state must not outlive the attempt. A stamp stuck on "Refreshing…" says the
        // console is working on it, which is the one thing that is definitely not true.
        console.error('[platform-actions] refreshQueues failed:', err);
        if (_sync) _sync.textContent = _t('Could not refresh. Press Refresh queues to try again', 'Hindi ma-refresh. Pindutin ang Refresh queues para subukan muli');
      } finally {
        _boxes.forEach(b => b.removeAttribute('aria-busy'));
      }
    }

    // One delegated listener for all moderation action buttons (data-attrs = XSS-safe).
    let _mktModWired = false;
    function wireMktModeration() {
      if (_mktModWired) return; _mktModWired = true;
      document.getElementById('sec-mkt-mod').addEventListener('click', async (ev) => {
        const btn = ev.target.closest('button[data-mkt-act]');
        if (!btn) return;
        const act = btn.dataset.mktAct;

        /* REFUSE BEFORE FIRING, NOT AFTER THE NETWORK EATS IT. Found 2026-08-04 by the live-MCP
           availability walk: offline, pressing Approve sent
           `PATCH marketplace_listings?id=eq...` into a dead network. Nothing landed -- the listing
           stayed draft with moderated_at null -- but ONLY because the transport failed. The admin got
           no refusal and no confirmation, so the one thing standing between "approved" and "not
           approved" was a request timing out.
           On this queue Approve publishes a listing to every buyer and Verify mints a trust badge, so
           an action that fires into the dark and reports nothing is worse than one that refuses. Every
           moderation action goes through this dispatcher, so the guard sits here once rather than at
           four call sites, and it says plainly that nothing was sent. */
        if (navigator.onLine === false) {
          showToast('You are offline, so nothing was sent. This action was not recorded: reconnect and press it again.', 'error');
          return;
        }

        /* GREYING OUT IS THE WEAKEST WAY TO SAY "WORKING". Measured 2026-08-04 on the live MCP
           browser: with the PATCH held open 1,300ms, three presses correctly produced ONE write, but
           across the whole flight the button read "Approve" and only went dim -- which on a queue
           where Approve publishes a listing to every buyer, and Verify mints a trust badge, is a
           thinner signal than the action deserves. Every other write path on this platform relabels
           (Saving.../Posting.../Hailing...), so this one does too, and aria-busy says it to a screen
           reader rather than leaving it to the colour. Restored beside btn.disabled on the error path;
           on success the queue refresh removes the row, button and all. */
        /* ONE restore, used by EVERY path that hands the control back -- including the three
           reject-reason early returns. Re-enabling without relabelling would leave a live button
           reading "Rejecting..." after the admin simply pressed Cancel. */
        const _btnRestore = () => {
          btn.disabled = false;
          btn.removeAttribute('aria-busy');
          if (btn.dataset.whLabel) btn.textContent = btn.dataset.whLabel;
        };
        btn.disabled = true;
        btn.dataset.whLabel = btn.textContent;
        btn.setAttribute('aria-busy', 'true');
        btn.textContent = act === 'approve-listing' ? 'Approving…'
                        : act === 'reject-listing'  ? 'Rejecting…'
                        : 'Verifying…';
        try {
          if (act === 'approve-listing' || act === 'reject-listing') {
            const newStatus = act === 'approve-listing' ? 'published' : 'removed';
            // MK2/J20 (deepwalk 2026-07-24): THIS is the live moderation surface (marketplace-admin.html
            // is retired behind #wh-retired-overlay and points here). A rejection must carry a reason back
            // to the seller — otherwise they see a bare red "Removed" chip with no way to fix and resubmit.
            // Kept in lockstep with founder-console.html + marketplace-admin.html: one authority, three surfaces.
            const _nowIso = new Date().toISOString();
            const _patch = { status: newStatus, updated_at: _nowIso, moderated_at: _nowIso,
                             // J20 (deepwalk 2026-07-24): neither console defines WORKER_NAME, so this always
                             // fell back to the literal 'admin' and the moderation record could not say WHO acted.
                             // whWorker() (utils.js) is the shared identity accessor both pages already load.
                             moderated_by: (typeof whWorker === 'function' && whWorker()) || 'admin' };
            if (act === 'reject-listing') {
              if (typeof whPrompt !== 'function') { _btnRestore(); showToast(_t('Cannot collect a rejection reason right now. Reload and try again.', 'Hindi makakuha ng dahilan ng pagtanggi ngayon. I-reload at subukan muli.'), 'error'); return; }
              let _reason = await whPrompt('Reject this listing. Tell the seller why:',
                { okLabel: 'Reject', cancelLabel: 'Cancel', inputLabel: 'Reason shown to the seller' });
              if (_reason === null) { _btnRestore(); return; }   // cancelled
              _reason = String(_reason).trim();
              if (!_reason) { _btnRestore(); showToast('A reason is required so the seller can fix and resubmit.', 'error'); return; }
              _patch.moderation_reason = _reason;
            } else {
              _patch.moderation_reason = null;   // approving clears a stale rejection note
            }
            const { data: _moderated, error } = await db.from('marketplace_listings')
              .update(_patch).eq('id', btn.dataset.id).select('id');
            if (error) throw error;
            // SL L2 (2026-10-21): a refused update matches zero rows and returns no error, and this said "Listing
            // approved: now live to buyers" about a listing that was not. The database records the decision
            // (platform_audit_log, moderated_by bound to this account) only when it lands, and so does this receipt.
            if (!_moderated || !_moderated.length) {
              _btnRestore();
              showToast('Nothing was saved: this listing may already have been decided, or this session is not a platform admin. Reload the queue to see where it stands.', 'error');
              return;
            }
            // J3 receipt: name what actually happened. "Listing rejected." left the admin unsure
            // whether the reason they were required to type ever reaches the seller. It does.
            showToast(act === 'approve-listing'
              ? 'Listing approved: now live to buyers.'
              : 'Listing rejected. The seller can see your reason and resubmit.',
              act === 'approve-listing' ? 'success' : 'info');
            if (typeof whUse === 'function') whUse(db, act === 'approve-listing' ? 'listing_approved' : 'listing_rejected');
          } else if (act === 'verify-kyb' || act === 'verify-cert') {
            // T67/T50 (2026-08-26): granting the badge BUYERS RELY ON asked nothing here either.
            // Names WHO, because in a per-seller row list the name is what a misclick gets wrong.
            if (typeof window.whConfirm === 'function') {
              const _who = btn.dataset.name || 'this seller';
              const _okV = await window.whConfirm(
                act === 'verify-kyb'
                  ? `Mark ${_who} as ID Verified? Buyers see this badge as WorkHive confirming their `
                    + `identity, and decide whether to send money on it.`
                  : `Mark ${_who}'s certifications as verified? Buyers read the badge as WorkHive `
                    + `having checked their trade credentials.`,
                { okLabel: 'Verify', cancelLabel: 'Cancel' });
              if (!_okV) { btn.disabled = false; return; }
            }
            const nowIso = new Date().toISOString();
            const upd = act === 'verify-kyb'
              ? { kyb_verified: true, kyb_verified_at: nowIso, updated_at: nowIso }
              : { cert_verified: true, cert_verified_at: nowIso, updated_at: nowIso };
            // ★BRP-A (2026-10-04): A TRUST BADGE MUST NOT BE WRITTEN BY DISPLAY NAME. This update sets
        // kyb_verified / cert_verified - the marketplace's verification badges - and it keyed on
        // btn.dataset.name, a mutable display string. Two sellers sharing a name, or a name that has
        // drifted from the row it was rendered from, and the verification lands on the WRONG seller or
        // on none at all (PostgREST answers a 0-row update with 204 and no error, so the admin is told
        // it worked). Measured: marketplace_sellers holds 16 rows with 0 duplicate worker_name today,
        // so this is latent rather than live - which is the right time to fix it. The row's PRIMARY KEY
        // is carried in the dataset instead, falling back to the name only if an older rendered DOM has
        // no id attribute, so nothing breaks mid-session.
        const _sellerId = btn.dataset.sellerId || '';
        // ★BY ID ONLY (2026-10-13): the by-name fallback is gone - the buttons and this handler come from the same page load and every button carries data-seller-id, so it never ran; had it run, it would have verified EVERY seller sharing the display name. A row without an id is refused, not guessed.
        if (!_sellerId) { showToast('This seller row has no id, so nothing was verified. Reload the queue and try again.', 'error'); return; }
        const { data: _verified, error } = await db.from('marketplace_sellers').update(upd).eq('id', _sellerId).select('id');
            if (error) throw error;
            // SL L2: confirmed before the receipt (a refused update is not an error), and recorded by the database -
            // platform_audit_log, bound to this account - not written into this operator's own hive trail
            if (!_verified || !_verified.length) {
              _btnRestore();
              showToast('Nothing was verified: this seller may already be verified, or this session is not a platform admin. Reload the queue to see where it stands.', 'error');
              return;
            }
            showToast((btn.dataset.name || 'Seller') + (act === 'verify-kyb' ? ' identity verified.' : ' certifications verified.'), 'success');
            if (typeof whUse === 'function') whUse(db, act === 'verify-kyb' ? 'seller_identity_verified' : 'seller_certs_verified');
          }
          /* The 'dispute-buyer' / 'dispute-seller' writer was RETIRED 2026-08-03 with the ghost table.
             Nothing emits those data-mkt-act values now, and leaving the writer would keep a live path
             into a retired table that no markup scan could see. */
          await refreshQueues();
        } catch (err) {
          console.error('[platform-actions] platform-actions action failed:', err);
          // Same rule as the marketplace inquiry step: only say "try again" when trying again could
          // actually work. A 42501/401 here means the admin session expired or the role no longer
          // resolves, and retrying will fail identically until they sign in again.
          const _refusal = refusalMessage(err);
          const _authFail = whIsAuthFailure(err);
          showToast(_refusal
            ? _refusal
            : _authFail
              ? 'Your admin session expired, so nothing was changed. Sign in again to continue moderating.'
              : _t('Action failed. Try again.', 'Hindi natuloy ang aksyon. Subukan muli.'), 'error');
          _btnRestore();
        }
      });
    }

    /* ── Feedback triage ────────────────────────────────────────────────────────────────────────
       Lifted from founder-console.html 2026-08-03. Everything load-bearing came with it — the
       optimistic-concurrency guard, the confirm before publishing to the public roadmap, and the
       per-item draft autosave — because each of those exists for a defect this platform already hit,
       and a lift that drops them re-opens all three. Two things are BETTER than the original: focus
       returns to the card the drawer was opened from (the console left it on <body>), and the empty
       state respects _sessionLimited instead of claiming an all-clear RLS never confirmed. */
    const _fb = { rows: [], activeTab: 'new', kindFilter: '*', searchTerm: '', drawerId: null,
                  channel: null, opener: null, openerIndex: -1, error: null };
    let _fbDraft = { clear: function () {} };

    function fbTimeAgo(iso) {
      const t = new Date(iso).getTime();
      if (isNaN(t)) return '';
      const d = (Date.now() - t) / 1000;
      if (d < 60) return Math.floor(d) + 's ago';
      if (d < 3600) return Math.floor(d / 60) + 'm ago';
      if (d < 86400) return Math.floor(d / 3600) + 'h ago';
      if (d < 86400 * 7) return Math.floor(d / 86400) + 'd ago';
      // one formatter, kept (SL LB3, 2026-10-21): toLocaleDateString builds a new one for every call, and with the
      // feedback list's 500 rows that was 141 ms of one render at phone speed - the same output, built once
      const f = fbTimeAgo.fmt || (fbTimeAgo.fmt = new Intl.DateTimeFormat(undefined, { timeZone: 'Asia/Manila' }));
      return f.format(new Date(iso));
    }

    async function fetchFeedback() {
      try {
        const { data, error } = await db.from('platform_feedback')
          .select('id,created_at,kind,rating,subject,body,status,priority,hive_id,worker_name,contact_email,page_url,admin_note,resolved_at,is_public,updated_at')
          .order('created_at', { ascending: false })
          .order('id')                       // MR4: the sort above is not total on its own
          .limit(500 + 1);   // more-said: by applyFeedbackView - the 'all' count says '500+' when a 501st exists (SL LB1)
        return { rows: (data || []).slice(0, 500), more: (data || []).length > 500, _error: error ? error.message : null,
                 _code: error ? (error.code || null) : null,
                 _status: error ? (error.status || error._httpStatus || null) : null };
      } catch (err) { return { rows: [], _error: err && err.message || 'fetch failed', _code: err && err.code || null, _status: err && (err._httpStatus || err.status) || null, _retryAfter: err && err.retryAfter || null }; }
    }

    function renderFeedback(m) {
      m = m || {};
      _fb.error = m._error || null;
      _fb.rows = m.rows || [];
      _fb.more = !!m.more;   // SL LB1
      applyFeedbackView();
    }

    function applyFeedbackView() {
      const list = document.getElementById('fb-list');
      if (!list) return;

      if (_fb.error) {
        // Third instance of the same shape on this page: the failure path writing a 0 into the badge,
        // so an unread feedback queue reads as an empty one. The gap says it does not know.
        list.innerHTML = `<div class="mod-empty">${e(_queueErr({ _error: _fb.error, _code: _fb.code, _status: _fb.status }))}</div>`;
        setCount('fb-count-badge', '—', '');
        ['new', 'triaged', 'in_progress', 'resolved', 'all'].forEach((k) => {
          const _el = document.getElementById('fb-count-' + k);
          if (_el && typeof whStatUnknown === 'function') whStatUnknown(_el, 'count');
        });
        return;
      }

      // Counts are over ALL rows, never the filtered view — a tab badge that moved when you typed
      // in the search box would make "3 new" unreadable as a workload.
      const counts = { new: 0, triaged: 0, in_progress: 0, resolved: 0, all: _fb.more ? '500+' : _fb.rows.length };   // SL LB1: a 501st row decides it   // cap is not a total (2026-09-05): the read is .limit(500)
      _fb.rows.forEach(r => { if (counts[r.status] !== undefined) counts[r.status]++; });
      // The tab pills are written directly rather than through setCount (which would impose its own
      // `count` class on a span that has none), so they carry the same guard explicitly. Without it the
      // five tabs read "New 0 / Triaged 0 / ..." for a reader the page has just told it cannot show the
      // queue to - and 10 'new' rows existed in the database at the moment that was measured.
      const _unknown = (typeof _sessionLimited !== 'undefined' && _sessionLimited);
      Object.entries(counts).forEach(([k, v]) => {
        const el = document.getElementById('fb-count-' + k);
        if (!el) return;
        if (_unknown && typeof whStatUnknown === 'function') whStatUnknown(el, 'count');
        else if (!_unknown && typeof whStatValue === 'function') whStatValue(el, v);
        else el.textContent = _unknown ? '\u2014' : v;
      });
      // The header badge counts what is WAITING (new + triaged + in progress), not the archive:
      // this page exists to answer "is anything owed", and 500 resolved items is not owed.
      const waiting = counts.new + counts.triaged + counts.in_progress;
      setCount('fb-count-badge', waiting, counts.new > 0 ? 'fail' : (waiting > 0 ? 'warn' : ''));

      let view = _fb.rows;
      if (_fb.activeTab !== '*') view = view.filter(r => r.status === _fb.activeTab);
      if (_fb.kindFilter !== '*') view = view.filter(r => r.kind === _fb.kindFilter);
      if (_fb.searchTerm) {
        const s = _fb.searchTerm.toLowerCase();
        view = view.filter(r => (r.subject || '').toLowerCase().includes(s) || (r.body || '').toLowerCase().includes(s));
      }

      if (!view.length) {
        const bare = (_fb.kindFilter !== '*' || _fb.searchTerm)
          ? 'Nothing matches the current filters.'
          : (_fb.activeTab === 'new'
              ? 'Nothing new. Messages sent from the widget on any page land here in real time.'
              : 'Nothing in this tab.');
        list.innerHTML = `<div class="mod-empty">${e(emptyText(bare))}</div>`;
        return;
      }

      // ★SL LB3 (2026-10-21, traced at 390 with the CPU 4x slower): a hundred cards, each a subject and a two-line
      // snippet of up to 220 characters, were laid out in one go - a 429 ms layout, the longest task on the page. They are
      // now a long list's rows (whRenderRows): the browser lays out only the cards near the screen, and a re-render (a
      // filter, a status change) replaces only the cards that changed. The cards sit in their own container, the note
      // under them in another.
      let rowsEl = list.querySelector(':scope > [data-fb-rows]');
      if (!rowsEl) {
        list.innerHTML = '<div data-fb-rows></div><div data-fb-more class="mod-empty" style="text-align:center" hidden></div>';
        rowsEl = list.firstElementChild;
      }
      whRenderRows(rowsEl, view.slice(0, 100), r => {
        const who = r.worker_name ? e(r.worker_name) : (r.hive_id ? e(r.hive_id.slice(0, 8)) : 'anonymous');
        const stars = (r.kind === 'review' && r.rating)
          ? `<span aria-label="${e(r.rating)} out of 5 stars">${'★'.repeat(r.rating)}${'☆'.repeat(5 - r.rating)}</span>` : '';
        return `<button class="fb-card" type="button" data-fb-id="${e(r.id)}"
                  aria-label="Triage feedback: ${e((r.subject || '(no subject)').slice(0, 60))}">
          <span class="fb-card-top">
            <span class="fb-kind">${e(r.kind)}</span>
            <span class="fb-status ${e(r.status)}">${e(String(r.status).replace('_', ' '))}</span>
            <span>${e(fbTimeAgo(r.created_at))} · ${who}</span>${stars}
            ${r.priority ? `<span class="fb-kind">${e(String(r.priority).toUpperCase())}</span>` : ''}
          </span>
          <span class="fb-subject">${e(r.subject || '(no subject)')}</span>
          <span class="fb-snippet">${e((r.body || '').slice(0, 220))}</span>
        </button>`;
      // the key is the card's own markup: it carries a relative time ("3m ago") that changes with no change to the row
      }, { key: 'html', long: true });
      const moreEl = list.querySelector(':scope > [data-fb-more]');
      moreEl.textContent = view.length > 100 ? `Showing the first 100 of ${view.length}. Narrow the filters to see more.` : '';
      moreEl.hidden = !(view.length > 100);
    }

    function openFeedbackDrawer(id, opener) {
      const row = _fb.rows.find(r => r.id === id);
      if (!row) return;
      _fb.drawerId = id;
      _fb.opener = opener || null;
      _fb.openerIndex = opener
        ? Array.prototype.indexOf.call(document.querySelectorAll('#fb-list .fb-card'), opener) : -1;
      const body = document.getElementById('fb-drawer-body');
      const stars = (row.kind === 'review' && row.rating)
        ? `<div class="fb-meta">${'★'.repeat(row.rating)}${'☆'.repeat(5 - row.rating)}</div>` : '';

      body.innerHTML = `
        <div class="fb-meta">${e(new Date(row.created_at).toLocaleString('en-PH', { timeZone: 'Asia/Manila' }))} · ${e(row.kind)}
          · status: <strong>${e(row.status)}</strong>${row.priority ? ' · ' + e(String(row.priority).toUpperCase()) : ''}</div>
        <div class="fb-subject" style="font-size:1rem;margin-top:.4rem">${e(row.subject || '(no subject)')}</div>
        ${stars}
        <div class="fb-body">${e(row.body || '')}</div>
        <div class="fb-meta">
          ${row.contact_email ? 'From: <strong>' + e(row.contact_email) + '</strong>' : 'Anonymous'}
          ${row.worker_name ? ' · worker: ' + e(row.worker_name) : ''}
          ${row.hive_id ? ' · hive: ' + e(row.hive_id.slice(0, 8)) : ''}
          ${row.page_url ? '<br/>Sent from: ' + e(row.page_url) : ''}
        </div>

        <label for="fb-d-status">Status</label>
        <select id="fb-d-status">
          ${['new','triaged','in_progress','resolved','wontfix','duplicate']
            .map(s => `<option value="${s}"${s === row.status ? ' selected' : ''}>${s}</option>`).join('')}
        </select>

        <label for="fb-d-priority">Priority</label>
        <select id="fb-d-priority">
          <option value="">(none)</option>
          ${['p0','p1','p2','p3'].map(p => `<option value="${p}"${p === row.priority ? ' selected' : ''}>${p.toUpperCase()}</option>`).join('')}
        </select>

        <label for="fb-d-note">Admin note (internal)</label>
        <textarea id="fb-d-note" placeholder="Triage notes for yourself…">${e(row.admin_note || '')}</textarea>

        <label style="display:flex;align-items:center;gap:.5rem;margin-top:1rem;cursor:pointer;text-transform:none;letter-spacing:0;color:#fff">
          <input type="checkbox" id="fb-d-public"${row.is_public ? ' checked' : ''} style="width:auto;min-height:0;cursor:pointer" />
          <span>Show on the public roadmap (/feedback/)</span>
        </label>
        <div class="fb-meta" style="margin-top:.35rem">Anyone can read a public item and Google can index it.
          Don't publish contact emails, worker names or internal notes.</div>

        <div class="fb-drawer-actions">
          <button type="button" class="mod-btn ok" id="fb-d-save" data-i="savechanges">Save changes</button>
          ${row.contact_email
            ? `<a class="mod-btn" href="mailto:${encodeURIComponent(row.contact_email)}?subject=${encodeURIComponent('Re: ' + (row.subject || 'your WorkHive feedback'))}">Reply via email</a>`
            : `<button type="button" class="mod-btn" disabled title="This person left no email" data-i="noemailtoreplyto">No email to reply to</button>`}
        </div>`;

      document.getElementById('fb-drawer').hidden = false;
      document.getElementById('fb-drawer-backdrop').hidden = false;
      setTimeout(() => document.getElementById('fb-d-status')?.focus(), 50);

      // X2 interruption resilience: triage notes are typed prose, and a reload or a phone call would
      // lose them. Keyed per feedback id so two open triages never overwrite each other.
      _fbDraft = (typeof whAutoSaveDraft === 'function')
        ? whAutoSaveDraft('fbtriage_' + id, ['fb-d-note'])
        : { clear: function () {} };

      document.getElementById('fb-d-save').onclick = () => saveFeedbackDrawer(id);
    }

    function closeFeedbackDrawer() {
      document.getElementById('fb-drawer').hidden = true;
      document.getElementById('fb-drawer-backdrop').hidden = true;
      _fb.drawerId = null;

      /* Return focus somewhere USABLE, not just to the opener. Restoring only the opening card is
         the obvious version and it fails in the single most common case: a successful triage moves
         the item out of the current tab, so the card is gone from the DOM and focus lands on <body>
         — measured on the first live walk of this lift, right after I claimed it was handled. A
         keyboard admin working a queue of ten would restart from the top of the page ten times.
         Fall back down a chain that always terminates: the same card → whatever card now sits at
         that position (the next item in the queue, which is where the work continues) → the last
         card → the active tab button, which always exists. */
      const opener = _fb.opener, idx = _fb.openerIndex;
      _fb.opener = null; _fb.openerIndex = -1;
      if (opener && document.body.contains(opener)) { opener.focus(); return; }
      const cards = document.querySelectorAll('#fb-list .fb-card');
      if (cards.length) { (cards[Math.min(idx, cards.length - 1)] || cards[0]).focus(); return; }
      document.querySelector('.fb-tab[aria-selected="true"]')?.focus();
    }

    async function saveFeedbackDrawer(id) {
      const status   = document.getElementById('fb-d-status').value;
      const priority = document.getElementById('fb-d-priority').value || null;
      const note     = document.getElementById('fb-d-note').value.trim() || null;
      const isPublic = document.getElementById('fb-d-public')?.checked || false;
      const btn      = document.getElementById('fb-d-save');
      const row      = _fb.rows.find(r => r.id === id);
      const wasPublic = !!row?.is_public;

      /* WCAG 3.3.4 error protection: publishing is hard to reverse — once /feedback/ is indexed the
         content can stay cached after un-publishing. Only the newly-public case is gated.
         whConfirm, not native confirm(): the founder-console original used the browser dialog, which
         is unstyled, unlocalisable, and blocks the whole tab. The shared modal is already on this
         page for the listing-rejection reason, so using it costs nothing and keeps one dialog. */
      if (isPublic && !wasPublic) {
        if (typeof whConfirm !== 'function') {
          showToast(_t('We cannot confirm publishing right now. Nothing changed, so reload and try again.', 'Hindi makumpirma ang pag-publish ngayon. Walang na-save, kaya i-reload at subukan muli.'), 'error');
          return;
        }
        const okToPublish = await whConfirm(
          'Publish this feedback to the PUBLIC roadmap (/feedback/)? It becomes visible to anyone and can be '
        + 'indexed by Google. Make sure it contains nothing private (contact email, worker name, internal notes).',
          { okLabel: 'Publish publicly', cancelLabel: 'Keep private' });
        if (!okToPublish) return;
      }

      // az_fail_offline: refuse the write AT THE DOOR when the connection is gone. A PATCH fired
      // offline leaves the page with an unknowable outcome — the server may or may not receive it,
      // so a retry risks applying the same triage twice. Refuse and say nothing was sent
      // (tests/failure-injection.spec.ts az_fail_offline holds every write surface to this).
      if (typeof navigator !== 'undefined' && navigator.onLine === false) {
        showToast('You appear to be offline. Nothing was sent: reconnect and save again.', 'error');
        return;
      }

      btn.disabled = true; btn.textContent = 'Saving…';
      try {
        // Optimistic concurrency: two admins triaging the same item would otherwise clobber each
        // other — including re-exposing a just-unpublished row. tg_touch_platform_feedback bumps
        // updated_at on every write, so a stale snapshot matches 0 rows instead of overwriting.
        const snap = row?.updated_at || null;
        let q = db.from('platform_feedback')
          .update({ status, priority, admin_note: note, is_public: isPublic }).eq('id', id);
        if (snap) q = q.eq('updated_at', snap);
        const { data: saved, error } = await q.select('id, updated_at');
        if (error) throw error;
        if (!saved || saved.length === 0) {
          btn.textContent = 'Save changes'; btn.disabled = false;
          showToast('Someone else changed this feedback. Your note was not saved, so reloading the latest.', 'error');
          closeFeedbackDrawer();
          renderFeedback(await fetchFeedback());
          return;
        }
        if (row) Object.assign(row, { status, priority, admin_note: note, is_public: isPublic,
          updated_at: saved[0].updated_at,
          resolved_at: ['resolved','wontfix','duplicate'].includes(status)
            ? (row.resolved_at || new Date().toISOString()) : row.resolved_at });
        applyFeedbackView();
        closeFeedbackDrawer();
        _fbDraft.clear();
        showToast(isPublic && !wasPublic ? 'Saved, and now public on /feedback/' : 'Saved.', 'success');
        if (typeof whUse === 'function') whUse(db, 'feedback_triaged', { status: String(status || ''), published: !!(isPublic && !wasPublic) });
      } catch (err) {
        console.error('[platform-actions] feedback save failed:', err);
        btn.textContent = 'Save changes'; btn.disabled = false;
        const refusal = refusalMessage(err);
        showToast(refusal
          ? refusal
          : (typeof whIsAuthFailure === 'function' && whIsAuthFailure(err))
            ? 'Your admin session expired, so nothing was saved. Sign in again to keep triaging.'
            : _t('Save failed. Try again.', 'Hindi na-save. Subukan muli.'), 'error');
      }
    }

    // Realtime INSERTs only — updates flow through the local cache above, so a save does not race
    // its own echo. Idempotent: re-entering is a no-op.
    function subscribeFeedbackRealtime() {
      if (_fb.channel) return;
      _fb.channel = db.channel('platform_feedback_inserts')
        .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'platform_feedback' }, payload => {
          const row = payload.new;
          if (!row || !row.id || _fb.rows.some(r => r.id === row.id)) return;
          _fb.rows.unshift(row);
          applyFeedbackView();
          showToast('New ' + row.kind + ' from ' + (row.worker_name || row.contact_email || 'anonymous'));
        })
        // SL AV3: the queues already re-read every 60 s (refreshQueues), so a blocked live channel needs no second poll -
        // only to say that new feedback arrives on that minute, not live
        .subscribe(typeof rtConn === 'function' ? rtConn(undefined, undefined, { name: 'the feedback inbox', pollMs: 60000 }) : undefined);

      /* BOTH events, because neither is sufficient alone and the channel is a server-side resource.
         `beforeunload` is the platform convention (every other channel page uses it, and the
         observability gate asserts it) but mobile Safari frequently never fires it, so a founder
         closing the tab on a phone would leak the subscription. `pagehide` covers that and the
         bfcache path. The teardown is idempotent -- it nulls _fb.channel -- so whichever fires
         first wins and the second is a no-op; `once` on each keeps the listeners from accumulating. */
      window.addEventListener('beforeunload', () => {
        if (_fb.channel) { db.removeChannel(_fb.channel); _fb.channel = null; }
      }, { once: true });
      window.addEventListener('pagehide', () => {
        if (_fb.channel) { db.removeChannel(_fb.channel); _fb.channel = null; }
      }, { once: true });
    }

    let _fbWired = false;
    function wireFeedback() {
      if (_fbWired) return; _fbWired = true;
      document.querySelectorAll('.fb-tab').forEach(btn => {
        btn.addEventListener('click', () => {
          _fb.activeTab = btn.dataset.status;
          document.querySelectorAll('.fb-tab').forEach(b => b.setAttribute('aria-selected', b === btn ? 'true' : 'false'));
          applyFeedbackView();
        });
      });
      document.getElementById('fb-filter-kind')?.addEventListener('change', ev => {
        _fb.kindFilter = ev.target.value; applyFeedbackView();
      });
      // SL LB3: the list follows the typing 150 ms after it pauses, so a keystroke paints at once
      const _fbSearchRender = debounce(applyFeedbackView, 150);
      document.getElementById('fb-filter-search')?.addEventListener('input', ev => {
        _fb.searchTerm = ev.target.value.trim(); _fbSearchRender();
      });
      if (typeof whAutoRememberFilters === 'function') whAutoRememberFilters('fb-filters', ['fb-filter-search']);
      // Delegated: the list is re-rendered on every filter keystroke, so per-card listeners would
      // be re-bound hundreds of times a session.
      document.getElementById('fb-list')?.addEventListener('click', ev => {
        const card = ev.target.closest('button[data-fb-id]');
        if (card) openFeedbackDrawer(card.dataset.fbId, card);
      });
      document.getElementById('fb-drawer-close')?.addEventListener('click', closeFeedbackDrawer);
      document.getElementById('fb-drawer-backdrop')?.addEventListener('click', closeFeedbackDrawer);
      document.addEventListener('keydown', ev => {
        if (ev.key === 'Escape' && _fb.drawerId) closeFeedbackDrawer();
      });
      subscribeFeedbackRealtime();
    }
    /* ★A 60s REFRESH RE-READ THE WHOLE FEEDBACK LIST (2026-10-06, platform-actions x assistive-tech, layer D). #fb-list
       is a polite live region on purpose - a filter or search change re-renders it and should be heard - but the minute's
       refresh rebuilt it with the same markup, and replacing nodes in a live region is an announcement. Its own innerHTML
       setter returns early when nothing changed and nothing else touched it since. (On Platform Actions this lived in the
       usage card's markup.) */
    (function () {
      var d = Object.getOwnPropertyDescriptor(Element.prototype, 'innerHTML');
      if (!d || !d.set || !d.get) return;
      ['fb-list'].forEach(function (id) {
        var el = document.getElementById(id);
        if (!el) return;
        Object.defineProperty(el, 'innerHTML', {
          configurable: true,
          get: function () { return d.get.call(this); },
          set: function (html) {
            if (this.__whLastHtml === html && this.__whLastDom === d.get.call(this)) return;
            d.set.call(this, html);
            this.__whLastHtml = html;
            this.__whLastDom = d.get.call(this);
          }
        });
      });
    })();
    // ── Started by the console once its own admin gate has passed ──
    // Platform Actions asked the server here who the visitor is; the console now does, and passes the answer in.
    // HONEST EMPTY, NOT A FALSE ALL-CLEAR (2026-08-03): on the founder's local bypass a session that is not a platform
    // admin reads every queue as empty with no error, so the queues say "not visible with this session" instead.
    _sessionLimited = opts.realAdmin === false;
    if (_sessionLimited) {
      const note = document.getElementById('local-bypass-note');
      if (note) {
        note.hidden = false;
        note.textContent = 'Local bypass: you are not signed in as a platform admin, so every queue below '
          + 'reads empty no matter what is actually waiting. Sign in as an admin to work them.';
      }
    }
    wireMktModeration();
    wireSvcTopups();
    wireFeedback();
    await refreshQueues();
    // ★NOT WHILE NOBODY IS LOOKING (SL LB4, 2026-10-22): whPoll skips a hidden tab and never runs two refreshes at once;
    // the console's own Refresh all re-reads the queues through api.refresh as well
    const _refreshPoll = whPoll(refreshQueues, 60000, { immediate: false });
    window.addEventListener('pagehide', () => _refreshPoll.stop(), { once: true });
    api.refresh = refreshQueues;
  };
  window.whOperatorActions = api;
})();
